import { inspectAccess, evaluateAccess } from './campus-model.js?v=access-20261009-r3';
import { REDUNDANCY_NODES, redundancyNodeName, redundancyEdges, evaluateRedundancy } from './campus-redundancy.js?v=access-20261009-r3';

export function initCampusExtensions(api) {
  const el=id=>document.getElementById(id),safe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const siteNames={public:'公开网站',course:'课程网站',lab:'实验网站'},siteIPs={public:'.100',course:'.102',lab:'.101'};
  const backup={enabled:true,failedNode:'none',failedLink:'none',manualTakeover:false,aclSynchronized:true};
  let auth=null,authTimer,backupTimer,backupStep=0,lastRequestStage;
  let grantFingerprint=JSON.stringify(api.getOptions().grants);
  const stopAuth=()=>{clearTimeout(authTimer);authTimer=null;};
  const stopBackup=()=>{clearTimeout(backupTimer);backupTimer=null;};
  function commitOnce(){if(auth.index>=4&&!auth.committed){auth.committed=true;api.commitGrant(auth.actor,auth.website,auth.allowed);}if(auth.index>=5&&!auth.synced){auth.synced=true;backup.aclSynchronized=true;el('backup-acl-sync').checked=true;renderBackup();}}
  function authStages(){
    const name=api.nodes[auth.actor].name,ip=api.nodes[auth.actor].ip,dst=`192.168.10${siteIPs[auth.website]}`,seq=auth.actor==='SB'?(auth.website==='course'?40:41):(auth.website==='course'?30:31),policy=auth.actor==='G1'?'GUEST_POLICY':'STUDENT_POLICY';
    const command=auth.allowed?`${seq} permit tcp host ${ip} host ${dst} eq 80`:`no ${seq}`;
    const outcome=evaluateAccess({...api.getOptions(),actor:auth.actor,target:auth.website,protocol:'http'});
    return [
      ['访问者提出申请',`${name} 请求${auth.allowed?'开放':'撤销'}${siteNames[auth.website]}；这里只处理这一台电脑和这一个网站。`,'申请内容没有改变 ACL，也还没有产生新许可。',0],
      ['教师核对授权范围',`教师确认来源 ${ip}、目的 ${dst}、TCP 80。${auth.allowed?'保留其他电脑、网站和协议的原有政策。':'只删除这一条许可。'}`,'教师是教学场景中的网络管理员，使用专用 AUTH-PC；普通教师电脑不能直接管理 R1。',0],
      ['从 AUTH-PC SSH 到 R1',`管理请求从 .114 → 管理交换路径 → R1 .113。VTY 的 MGMT_ONLY 只许可 AUTH 的来源 IP。`,'ssh -l labteacher 192.168.10.113\nSSH 登录还需有效凭据；动画省略实际登录。',1],
      ['准备精确的 ACL 修改',`在 ${policy} ${auth.allowed?'新增指定 HTTP 许可，放在最终 deny 前':'只删除固定序号的许可'}。这一步展示准备下发的命令。`,`ip access-list extended ${policy}\n ${command}\nHSRP 不会复制 ACL：冗余版还需单独同步并验证 R2。`,2],
      ['R1 应用规则，许可状态改变',`${name} 的${siteNames[auth.website]} HTTP 许可已${auth.allowed?'授予':'撤销'}。当前网页模型在到达这一阶段时才改变状态。`,`${command}\n回看前面的阶段不会撤回已执行的修改；真正撤销需播放撤销流程。`,2],
      ['管理员单独同步备用 R2',`AUTH-PC 登录 R2 的实际管理地址 .120，复制同一条 ACL 修改，再核对访问规则。此阶段代表管理员完成独立下发，不是 HSRP 自动同步。`,`${command}\nshow access-lists\n两路由器网站访问政策一致，才恢复备用路径放行。`,4],
      ['重新发起访问，核对首条匹配',`新的 HTTP 请求：${outcome.allowed?'访问成功':'访问未成功'}。${outcome.reason}`,'show access-lists\n保存配置后，比较另一个网站、其他电脑、ping 和 SSH。',3]
    ];
  }
  function renderAuth(){
    const stages=auth?authStages():null;
    el('auth-stages').innerHTML=stages?stages.map((s,i)=>`<span class="flow-stage ${i===auth.index?'current':i<auth.index?'complete':''}">${i+1} ${safe(s[0])}</span>`).join(''):'<p>选择上方的授权对象与网站，再播放下面的授权流程。申请和准备命令不会立刻放行；第 5 阶段才应用修改。</p>';
    if(auth){const stage=stages[auth.index];el('auth-heading').textContent=stage[0];el('auth-description').textContent=stage[1];el('auth-command').textContent=stage[2];el('auth-packet').setAttribute('cx',[85,365,635,870,635][stage[3]]);el('auth-packet').setAttribute('cy',stage[3]===4?'154':'14');}
    el('auth-prev').disabled=!auth||auth.index===0;el('auth-next').disabled=!auth||auth.index===6;
    el('auth-autoplay').disabled=!auth;el('auth-autoplay').textContent=authTimer?'暂停流程':'自动播放流程';
  }
  function authAdvance(delta){stopAuth();if(!auth)return;auth.index=Math.max(0,Math.min(6,auth.index+delta));commitOnce();renderAuth();}
  function authPlay(){if(authTimer){stopAuth();renderAuth();return;}if(!auth||auth.index===6)return;function tick(){auth.index++;commitOnce();renderAuth();if(auth.index<6){authTimer=setTimeout(tick,2400);renderAuth();}else{stopAuth();renderAuth();}}authTimer=setTimeout(tick,2400);renderAuth();}
  function startAuth(allowed){stopAuth();stopBackup();const scope=api.getGrantScope();auth={...scope,allowed,index:0,committed:false};api.setView('demo');renderAuth();authPlay();}
  el('authorization-walkthrough').innerHTML=`<section class="extension-card auth-flow"><div class="extension-heading"><div><span class="eyebrow">把授权过程讲出来</span><h3>申请不会直接变成访问许可</h3></div><div class="extension-actions"><button id="animate-grant" class="primary">演示授权过程</button><button id="animate-revoke">演示撤销过程</button></div></div><div id="auth-stages" class="flow-stages"></div><svg class="auth-network" viewBox="0 0 960 170" role="img" aria-label="管理授权路径：访问者申请，教师在 AUTH-PC 审核，通过 SSH 修改 R1，然后测试网站"><path d="M85 50 H870" stroke="#aabec3" stroke-width="3"/><g>${[[85,'访问者申请'],[365,'AUTH-PC · 审核'],[635,'R1 · 应用 ACL'],[870,'新请求验证']].map(([x,name])=>`<rect x="${x-77}" y="25" width="154" height="55" rx="9" fill="white" stroke="#c5d6d8"/><text x="${x}" y="58" text-anchor="middle" fill="#123c39" font-size="18">${name}</text>`).join('')}</g><path d="M635 80 V100" stroke="#aabec3" stroke-dasharray="5 5"/><rect x="558" y="100" width="154" height="40" rx="9" fill="#edf3f8" stroke="#b5c9d4"/><text x="635" y="126" text-anchor="middle" fill="#123c39" font-size="18">R2 · 单独同步</text><circle id="auth-packet" cx="85" cy="14" r="9" fill="#278660"/></svg><h4 id="auth-heading">等待选择授权流程</h4><p id="auth-description">教学动画模拟教师通过管理终端修改访问规则，不会登录或配置真实设备。</p><pre id="auth-command">许可仅覆盖所选电脑 → 所选网站 → TCP 80。</pre><div class="extension-actions"><button id="auth-prev">上一阶段</button><button id="auth-autoplay">自动播放流程</button><button id="auth-next">下一阶段</button></div></section>`;
  el('animate-grant').addEventListener('click',()=>startAuth(true));el('animate-revoke').addEventListener('click',()=>startAuth(false));el('auth-prev').addEventListener('click',()=>authAdvance(-1));el('auth-next').addEventListener('click',()=>authAdvance(1));el('auth-autoplay').addEventListener('click',authPlay);
  el('request-inspector').innerHTML=`<section class="extension-card request-inspector"><span class="eyebrow">访问不是只看“是谁”</span><h3>这次请求带了什么？在哪一条被决定？</h3><div id="request-fields" class="request-fields"></div><p id="request-location" role="status"></p><div class="extension-actions"><button data-probe="ssh-management">访客尝试 SSH 管理</button><button data-probe="ssh-server">学生尝试 SSH 网站</button><button data-probe="ping-server">学生 ping 网站</button><button data-probe="http">正常 HTTP 访问</button></div><details><summary>逐条查看 ACL 检查与拦截原因</summary><div id="acl-trace"></div></details><details class="security-boundary"><summary>ACL 能拦什么？哪些还需要网站自身保护？</summary><p>ACL 按来源 IP、目标 IP、协议和端口筛选。例如网页许可为 TCP 80，不会自动放行 SSH 22、ping 或 HTTPS 443。不同协议本身不代表恶意，只是本实验没有许可。</p><p>源 IP 不能证明真实用户身份。实际网站还需要登录、角色权限、HTTPS，以及按需要配置防火墙或 WAF；ACL 无法识别网页内容中的 SQL 注入、恶意上传等应用层攻击。本动画不模拟攻击内容检测、完整连接状态或限速。</p><p>拦截点：学生、访客、教师来源 VLAN 的 R1 入方向。被 deny 的请求停在 R1；同 VLAN 设备之间的流量需要另外的保护措施。</p></details></section>`;
  for(const button of document.querySelectorAll('[data-probe]'))button.addEventListener('click',()=>{
    const cases={'ssh-management':{actor:'G1',target:'management',protocol:'ssh'},'ssh-server':{actor:'SA',target:'course',protocol:'ssh'},'ping-server':{actor:'SA',target:'public',protocol:'icmp'},http:{actor:'G1',target:'public',protocol:'http'}};
    const input=cases[button.dataset.probe];for(const [key,value]of Object.entries(input)){el(key).value=value;el(key).dispatchEvent(new Event('change',{bubbles:true}));}api.setView('demo');
  });
  function renderInspector(){
    const info=inspectAccess(api.getOptions());
    const protocol=info.protocol==='http'?'TCP / HTTP':info.protocol==='ssh'?'TCP / SSH':'ICMP Echo';
    const fields=[['来源 IP / VLAN',info.source.ip+' / VLAN '+info.source.vlan],['目的 IP / VLAN',info.destination.ip+' / VLAN '+info.destination.vlan],['协议 / 目的端口',protocol+(info.port?' / '+info.port:' / 无 TCP 端口')],['检查入口',info.source.policyName+' · G0/0.'+info.source.vlan+' in']];
    el('request-fields').innerHTML=fields.map(([name,value])=>`<div><span>${name}</span><b>${safe(value)}</b></div>`).join('');
    el('acl-trace').innerHTML=info.trace.map(row=>{
      const status=row.state==='skipped'?'已结束，不再检查':row.state==='miss'?'条件不匹配，继续':row.state==='permit'?'首条匹配：放行':'首条匹配：拦截';
      const checks=row.checks.map(check=>(check.field==='actor'?'来源':check.field==='target'?'目标':'协议')+' '+(check.matches?'匹配':'不匹配')).join('；');
      return `<div class="trace-row ${row.state}"><b>${row.seq}</b><code>${safe(row.text)}</code><span>${status}</span><p>${safe(row.explanation)}${checks?' · '+safe(checks):''}</p></div>`;
    }).join('');
    requestStage(lastRequestStage);
  }
  function requestStage(step){lastRequestStage=step;if(!el('request-location'))return;const info=inspectAccess(api.getOptions());el('request-location').textContent=step?`当前动画：${step.title}。首条匹配为 ${info.result.policyName} ${info.result.rule.seq}：${info.result.networkAllowed?'permit':'deny'}。`:'请求使用电脑的固定 IP，不使用真人登录身份；点击下方播放查看经过的设备。';}
  const nodeOptions=Object.entries(REDUNDANCY_NODES).flatMap(([id,n])=>[[id,`${n.name}（主）`],[`${id}-B`,`${n.backup}（备）`]]).map(([id,name])=>`<option value="${id}">${name}</option>`).join('');
  const linkOptions=redundancyEdges().map(([a,b])=>`<option value="${a}|${b}">${redundancyNodeName(a)} ↔ ${redundancyNodeName(b)}</option>`).join('');
  el('panel-backup').innerHTML=`<div class="extension-card"><span class="eyebrow">冗余扩展 · 单个故障实验</span><h3>每个节点 1 主 + 1 备，权限始终保持</h3><p>使用“动画与授权”页的访问者、目标和权限。扩展拓扑新增 SRV-SW、MGMT-SW，端点经接入交换机连接双核心；五个 VLAN 保持分区。主设备与备用设备各 16 台，共 32 台。</p><div class="backup-controls"><label class="check-label"><input id="backup-enabled" type="checkbox" checked>启用备用设备和备用上联</label><label>模拟设备故障<select id="backup-node"><option value="none">没有设备故障</option>${nodeOptions}</select></label><label>模拟链路故障<select id="backup-link"><option value="none">没有链路故障</option>${linkOptions}</select></label><label class="check-label"><input id="backup-acl-sync" type="checkbox" checked>管理员已核对 R2 的 ACL 同步</label></div><div class="extension-actions"><button id="backup-play" class="primary">播放故障与切换</button><button id="backup-next">下一阶段</button><button id="backup-manual">手动换线／启用备用终端</button><button id="backup-restore">恢复主设备与链路</button></div><div id="backup-stages" class="flow-stages"></div><div id="backup-result" role="status"></div><div class="backup-diagram-scroll"><svg id="backup-diagram" viewBox="0 0 1100 370" role="img" aria-label="当前主备设备路径，虚线为待命链路，彩色线路为本阶段的访问路径"></svg></div><p id="backup-path"></p><p class="model-note">这是逻辑路径与收敛过程的教学模型：预设 VLAN、RSTP、HSRP 和双核心上联已正确配置，只注入一个故障。切换时延是动画节奏；不模拟全部控制报文、连接状态、实际收敛秒数或完整 TCP 重试。终端和服务器备用接管采用手动换线／恢复地址与服务；不是自动双机热备。</p></div><details class="extension-card" open><summary>每个节点的备用数量与接管方式</summary><div class="table-scroll"><table><thead><tr><th>主节点</th><th>备用节点</th><th>数量</th><th>接管条件</th></tr></thead><tbody>${Object.entries(REDUNDANCY_NODES).map(([id,n])=>`<tr><th>${n.name}</th><td>${n.backup}</td><td>1 主 + 1 备</td><td>${n.kind==='router'?'HSRP 虚拟网关；另行复制并验证 ACL':n.kind==='core'?'接入交换机双上联；RSTP 防环与重算':n.kind==='access'?'备用上联已接通；单网线端点须手动移线':n.kind==='server'?'主机离线后，手动启用备用 HTTP 服务与原地址':'主机离线后，手动替换终端，恢复原地址与网关'}</td></tr>`).join('')}</tbody></table></div><p>备用电脑／服务器接管原逻辑地址前，原设备必须离线，避免重复 IP。源 IP 保持只用于本教学实验，不等于认证了使用者。</p></details>${backupGuide()}`;
  function resetBackup(){stopBackup();backupStep=0;backup.manualTakeover=false;renderBackup();}
  el('backup-node').addEventListener('change',()=>{backup.failedNode=el('backup-node').value;backup.failedLink='none';el('backup-link').value='none';resetBackup();});
  el('backup-link').addEventListener('change',()=>{backup.failedLink=el('backup-link').value;backup.failedNode='none';el('backup-node').value='none';resetBackup();});
  el('backup-enabled').addEventListener('change',()=>{backup.enabled=el('backup-enabled').checked;resetBackup();});
  el('backup-acl-sync').addEventListener('change',()=>{backup.aclSynchronized=el('backup-acl-sync').checked;resetBackup();});
  el('backup-manual').addEventListener('click',()=>{stopBackup();backup.manualTakeover=true;backupStep=3;renderBackup();});
  el('backup-restore').addEventListener('click',()=>{backup.failedNode='none';backup.failedLink='none';el('backup-node').value='none';el('backup-link').value='none';resetBackup();});
  el('backup-next').addEventListener('click',()=>{stopBackup();backupStep=Math.min(3,backupStep+1);renderBackup();});
  el('backup-play').addEventListener('click',()=>{if(backupTimer){stopBackup();renderBackup();return;}stopAuth();backupStep=0;renderBackup();function tick(){backupStep++;renderBackup();if(backupStep<3){backupTimer=setTimeout(tick,2000);}else stopBackup();el('backup-play').textContent=backupTimer?'暂停切换':'播放故障与切换';}backupTimer=setTimeout(tick,2000);el('backup-play').textContent='暂停切换';});
  function renderBackup(){
    const options=api.getOptions(),result=evaluateRedundancy(backup,options),normal=evaluateRedundancy({...backup,failedNode:'none',failedLink:'none',manualTakeover:false},options),shown=backupStep<2?normal:result;
    const failed=backup.failedNode!=='none'?redundancyNodeName(backup.failedNode):backup.failedLink!=='none'?backup.failedLink.split('|').map(redundancyNodeName).join(' ↔ '):'无';
    el('backup-stages').innerHTML=['正常路径','检测故障','重新选择路径','验证权限与回程'].map((name,i)=>`<span class="flow-stage ${i===backupStep?'current':i<backupStep?'complete':''}">${i+1} ${name}</span>`).join('');
    const summary=backupStep===0?'先观察正常的主路径。':backupStep===1?`检测到故障对象：${failed}。检查备用设备、备用上联及控制协议。`:result.reason;
    el('backup-result').className=`backup-result ${backupStep>=2?(result.allowed?'success':'failure'):''}`;
    el('backup-result').innerHTML=`<b>${safe(api.nodes[options.actor].name)} → ${safe(siteNames[options.target]||api.nodes[options.target==='teacher'?'TA':'AUTH'].name)} · ${safe(options.protocol.toUpperCase())}</b><p>${safe(summary)}</p>${backupStep>=2?`<p>链路：${result.connected?'已连通':'未连通'} · 策略：${!result.policyAvailable?'R2 待同步':result.policy.networkAllowed?'permit':'deny'} · 本次访问：${result.allowed?'成功':'未成功'}</p>`:''}`;
    el('backup-next').disabled=backupStep===3;
    el('backup-manual').disabled=!backup.enabled||backup.failedNode==='none'&&backup.failedLink==='none'||backup.manualTakeover;
    const actor=options.actor,access={SA:'SS',SB:'SS',TA:'TS',G1:'GS'}[actor],target={public:'PUB',course:'COURSE',lab:'LAB',teacher:'TA',management:'AUTH'}[options.target],destinationAccess=options.target==='teacher'?'TS':options.target==='management'?'MGMT':'SERV';
    const columns=[actor,access,'CORE','R1',destinationAccess,target],xs=[90,275,460,645,830,1015];
    const points=new Map();let svg='';
    for(const [i,id]of columns.entries())for(const standby of [false,true]){const node=standby?`${id}-B`:id,key=`${node}:${i}`,x=xs[i],y=standby?255:95;points.set(key,{x,y,node,index:i});}
    const coordinate=(id,previousIndex=-1)=>{const candidates=[...points.values()].filter(p=>p.node===id);return candidates.find(p=>p.index>=previousIndex)||candidates[0];};
    // Physical primary/standby visual lanes; core is traversed twice by routed packets.
    for(let i=0;i<5;i++)for(const standby of [false,true]){const y=standby?255:95;svg+=`<path d="M${xs[i]} ${y} L${xs[i+1]} ${y}" stroke="${standby?'#9ebac9':'#bacbd0'}" stroke-dasharray="${standby?'7 7':'none'}" fill="none" stroke-width="3"/>`;}
    svg+='<text x="20" y="28" fill="#486068" font-size="19">主设备</text><text x="20" y="198" fill="#486068" font-size="19">备用设备与备用上联（路径示意）</text>';
    const coordinates=shown.path.map(id=>coordinate(id)).filter(Boolean);
    if(coordinates.length>1)svg+=`<polyline points="${coordinates.map(p=>`${p.x},${p.y}`).join(' ')}" stroke="${backupStep>=2&&!result.allowed?'#b3453d':'#21865d'}" fill="none" stroke-width="6" opacity=".8"/>`;
    for(const p of points.values()){const used=shown.path.includes(p.node),down=backupStep>=1&&p.node===backup.failedNode;svg+=`<g><rect x="${p.x-78}" y="${p.y-30}" width="156" height="60" rx="9" fill="${down?'#fff0eb':used?'#e8f6ed':'white'}" stroke="${down?'#b3453d':used?'#21865d':'#bacbd0'}" stroke-width="${down||used?3:1.5}"/><text x="${p.x}" y="${p.y-3}" text-anchor="middle" fill="#153e39" font-size="18">${safe(redundancyNodeName(p.node))}</text><text x="${p.x}" y="${p.y+20}" text-anchor="middle" fill="#5a7077" font-size="16">${down?'故障':used?'本阶段路径':'待命'}</text></g>`;}
    if(coordinates.length){const motionPath=coordinates.map((point,i)=>`${i?'L':'M'}${point.x} ${point.y}`).join(' ');svg+=`<circle r="9" fill="${shown.allowed?'#21865d':'#b3453d'}" stroke="white" stroke-width="3"><animateMotion dur="5s" repeatCount="indefinite" path="${motionPath}"/></circle>`;}
    svg+='<text x="25" y="345" fill="#486068" font-size="17">去网关与返回核心属于同一套交换网络；下方文字列出实际选中的完整路径。</text>';
    el('backup-diagram').innerHTML=svg;
    el('backup-path').innerHTML=`<b>本阶段去程：</b>${shown.path.map(id=>safe(redundancyNodeName(id))).join(' → ')}${backupStep===3&&result.reply.length?`<br><b>完整回程：</b>${result.reply.map(id=>safe(redundancyNodeName(id))).join(' → ')}`:''}`;
    return result;
  }
  function backupGuide(){return `<details class="extension-card"><summary>Packet Tracer 冗余版搭建提案与验收</summary><p>另存新实验，不把以下地址直接叠加到原版。冗余版保留原网关地址作为 HSRP 虚拟 IP；R1、R2 分别使用不同的真实接口地址。以下配置是进阶参考，尚未在本机 Packet Tracer 预实验；先核实所选设备支持 HSRP 与 rapid-pvst。</p><div class="table-scroll"><table><thead><tr><th>VLAN</th><th>虚拟网关</th><th>R1 实际接口</th><th>R2 实际接口</th></tr></thead><tbody>${[[10,'.1','.2','.3'],[20,'.65','.68','.69'],[30,'.97','.98','.99'],[99,'.113','.119','.120'],[40,'.129','.131','.132']].map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>所有 .x 都以 192.168.10 开头。CORE-SW-B、STU-SW-B、TCH-SW-B、GUEST-SW-B 管理地址可用 .121–.124；新 SRV-SW、MGMT-SW 与它们的备用交换机默认只做二层转发，如需管理地址应重新规划管理子网。备用端点手动接管原地址时必须先让主端点离线。</p><ol><li>两台核心的 Fa0/2 互连 trunk；CORE Fa0/1 接 R1 G0/0，CORE-B Fa0/1 接 R2 G0/0。核心 Fa0/3–12 依次接 STU、STU-B、GUEST、GUEST-B、TCH、TCH-B、SRV、SRV-B、MGMT、MGMT-B。每台接入交换机 G0/1 上联主核心、G0/2 上联备用核心。所有 trunk 放行五个 VLAN，交换机之间不要使用 PortFast。</li><li>两核心启用 rapid-pvst，并为所有 VLAN 分别设 root primary、root secondary；备用链路由 RSTP 防止二层环路。PC/服务器只有一条活动网线；接入交换机故障时移到备用接入交换机对应 access VLAN 端口。</li><li>R1/R2 的五个子接口配置同 VLAN 的 HSRP 组与虚拟 IP。R1 较高优先级，R2 较低；检查 show standby brief。主网关 trunk/core 失效时，HSRP 通过失去 hello 或已配置的跟踪条件切换。</li><li>两路由器都部署相同的访问政策、授权许可与 SSH 来源限制。学生、教师、访客的入方向 ACL 还需允许对应对等路由器的 HSRP 控制报文，否则最终 deny 会阻断 hello。HSRP v2 使用 UDP 1985 到 224.0.0.102；v1 使用 224.0.0.2。版本及例外必须与设备配置一致，不能用 permit ip any any 代替。</li><li>停止 R1、断开核心或上联、停止接入交换机，分别测试恢复。恢复后复测公开、课程、实验网站；未授权请求、网站 SSH、管理区访问仍应受限。保存故障前、故障后及恢复后的 .pkt 和测试截图。</li></ol><details><summary>VLAN 10 的 HSRP v2 配置示例（仅此 VLAN，须扩展到其余四个）</summary><p>两台路由器先定义完整 STUDENT_POLICY，再分别配置子接口。原版 .1 从实际接口地址改为虚拟网关，原版网页政策中“ping 自己网关”仍指 .1。</p><h4>两台路由器 STUDENT_POLICY 的控制报文例外</h4><pre>ip access-list extended STUDENT_POLICY\n 5 permit udp host 192.168.10.2 host 224.0.0.102 eq 1985\n 6 permit udp host 192.168.10.3 host 224.0.0.102 eq 1985\nexit</pre><h4>R1 的 VLAN 10 子接口</h4><pre>interface g0/0.10\n encapsulation dot1Q 10\n ip address 192.168.10.2 255.255.255.192\n standby version 2\n standby 10 ip 192.168.10.1\n standby 10 priority 110\n standby 10 preempt\n ip access-group STUDENT_POLICY in</pre><h4>R2 的 VLAN 10 子接口</h4><pre>interface g0/0.10\n encapsulation dot1Q 10\n ip address 192.168.10.3 255.255.255.192\n standby version 2\n standby 10 ip 192.168.10.1\n standby 10 priority 100\n standby 10 preempt\n ip access-group STUDENT_POLICY in</pre><p>其余 VLAN 使用各自实际地址、虚拟地址、组号与入口 ACL；为教师和访客的 ACL 添加各自对等路由器的 hello 例外。配置完成还需在父接口 no shutdown，并验证 trunk、完整 ACL、HSRP 报文和两端连通性。</p></details><p><a href="https://www.cisco.com/c/en/us/support/docs/ip/hot-standby-router-protocol-hsrp/9281-3.html" target="_blank" rel="noreferrer">Cisco HSRP 说明</a> · <a href="https://www.cisco.com/c/en/us/support/docs/lan-switching/spanning-tree-protocol-stp-8021d/218321-configure-stp-with-loop-guard-and-bpdu-s.html" target="_blank" rel="noreferrer">Cisco STP 防环说明</a></p></details>`;}
  function deviceBackupInfo(id){const node=REDUNDANCY_NODES[id];return node?`<div class="device-backup"><b>冗余数量：1 主 + 1 备</b><p>备用：${safe(node.backup)}。${node.kind==='router'?'通过 HSRP 接管虚拟网关；ACL 需要管理员独立同步。':node.kind==='core'?'双核心上联与 RSTP 提供备用路径。':'普通终端为单网线，故障后需要手动换线、替换或恢复服务。'}</p><p>在“故障与备份”页注入故障并验证权限是否保持。</p></div>`:'';}
  function refresh(){const fingerprint=JSON.stringify(api.getOptions().grants);if(fingerprint!==grantFingerprint){grantFingerprint=fingerprint;backup.aclSynchronized=false;el('backup-acl-sync').checked=false;}if(auth){const scope=api.getGrantScope();if(scope.actor!==auth.actor||scope.website!==auth.website){stopAuth();auth=null;renderAuth();}}renderInspector();renderBackup();}
  window.addEventListener('pagehide',()=>{stopAuth();stopBackup();});
  renderAuth();refresh();
  return {refresh,requestStage,deviceBackupInfo,stopBackup,stopAuthorization:() => {stopAuth();renderAuth();}};
}
